insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-rugby-l-amarillo', 'Juguete Rugby L - Amarillo', 'Su balón de rugby puede esconder algo más que ganas de jugar. Esta versión tiene aberturas para colocar snacks y convertir cada movimiento en una oportunidad de conseguir un premio. La forma ovalada y las distintas texturas le dan a tu perro más detalles para explorar mientras se entretiene.', 'L, 15,3 cm', (select id from public.categories where slug = 'juguetes-juguetes'), 'Talla', true, -1930) on conflict (slug) do nothing;
