insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-tripode-m', 'Juguete Trípode M', 'A veces, cambiar la forma del juguete es suficiente para renovar su curiosidad. El Trípode M tiene tres brazos con superficies distintas que invitan a explorar con la boca. Su mezcla de relieves y colores le da variedad al juego diario en un formato de 10 x 12 cm.', 'M, 10 x 12 cm', (select id from public.categories where slug = 'juguetes-juguetes'), 'Talla', true, -1880) on conflict (slug) do nothing;
