insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-boom-gigante-amarillo', 'Pelota Boom gigante - Amarillo', 'Para darle un nuevo giro al juego de la pelota. La Boom gigante tiene 15,2 cm de diámetro y una superficie con puntas que favorece los rebotes impredecibles. Su diseño de dos colores llama la atención desde el primer momento y anima a tu perro a seguir su recorrido.', 'Gigante, 15,2 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1870) on conflict (slug) do nothing;
