insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-boom-grande-azul', 'Pelota Boom grande - Azul', 'Un rebote inesperado basta para despertar sus ganas de jugar. La Boom grande combina una estructura redondeada con puntas y relieves que cambian la manera en que se mueve. Sus colores contrastantes le dan una apariencia divertida para acompañar esos ratos en los que tu perro quiere perseguir algo diferente.', 'Grande, 12,7 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1850) on conflict (slug) do nothing;
