insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-dispensadora-sensory-ball', 'Pelota dispensadora Sensory Ball', 'Encontrar un premio puede hacer que una pelota sea todavía más interesante. La Sensory Ball permite colocar snacks en su interior para que tu perro se entretenga intentando sacarlos mientras juega. Sus franjas de distintos colores y texturas le ofrecen más detalles para explorar en cada movimiento.', '8,3 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1830) on conflict (slug) do nothing;
