insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-grande-track-azul', 'Pelota grande Track - Azul', 'Una pelota que cambia de dirección convierte cada lanzamiento en una nueva oportunidad de perseguirla. La Track grande tiene relieves, superficies de distintas formas y sonido para mantener interesante el juego. Su formato de 9,8 cm y su mezcla de colores le dan una presencia que difícilmente pasará desapercibida.', 'Grande, 9,8 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1820) on conflict (slug) do nothing;
