insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-maciza-basket-gigante-azul', 'Pelota maciza Basket gigante - Azul', 'Hay perros que ven un balón y enseguida quieren entrar al juego. Esta versión gigante de la Basket ofrece un formato de 9 cm, con cuerpo macizo y una textura de pequeños relieves. Sus colores contrastantes y su estilo deportivo la convierten en una compañera llamativa para compartir una tarde de juegos.', 'Gigante, 9 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1800) on conflict (slug) do nothing;
