insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-maciza-basket-mediana-roja', 'Pelota maciza Basket mediana - Roja', 'Para ese compañero que siempre encuentra energía para una ronda más. La Basket mediana tiene un cuerpo macizo y una superficie con pequeños relieves que hacen más interesante el contacto con el juguete. Su diseño de baloncesto queda listo para acompañar los juegos de buscar y traer de cada día.', 'Mediana, 6,5 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1780) on conflict (slug) do nothing;
