insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-maciza-futbol-gigante-roja', 'Pelota maciza Fútbol gigante - Roja', 'Tu perro también puede tener su propio balón para salir a jugar. Esta pelota de fútbol combina un formato macizo con relieves en la superficie y colores que se hacen notar. Es una forma sencilla de invitarlo a perseguir, buscar y compartir contigo un rato de movimiento.', 'Gigante, 9 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1760) on conflict (slug) do nothing;
