insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-maciza-volley-mediana-azul', 'Pelota maciza Volley mediana - Azul', 'Si aparece una pelota, seguro querrá que el juego empiece de inmediato. La Volley tiene un diseño macizo y compacto, con pequeños relieves que le dan una textura diferente al morderla. Su apariencia de balón de voleibol pone un toque deportivo a esos momentos de lanzar, buscar y volver por más.', 'Mediana, 6,5 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1740) on conflict (slug) do nothing;
