insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('pelota-mediana-track-amarillo', 'Pelota mediana Track - Amarillo', 'Nunca sabes hacia dónde irá el siguiente rebote, y ahí empieza la diversión. La Track mediana combina formas y texturas que hacen variar su recorrido, invitando a tu perro a seguirla con atención. Además, tiene sonido para darle otro motivo para acercarse, explorar y continuar jugando.', 'Mediana, 8,3 cm de diámetro', (select id from public.categories where slug = 'juguetes-pelotas'), 'Talla', true, -1720) on conflict (slug) do nothing;
