insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-deluxe-colita-felina', 'Juguete Deluxe Colita felina', 'Una colita pequeña puede despertar una gran curiosidad. Este juguete suave y ligero contiene catnip y tiene un formato que tu gato puede atrapar entre sus patas o llevar a su rincón favorito. Su divertida silueta felina le da un toque especial a esos ratos de juego por toda la casa.', '8 x 4,5 cm', (select id from public.categories where slug = 'gatos-juguetes-para-gato'), 'Talla', true, -1700) on conflict (slug) do nothing;
