insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-deluxe-colita-gatuna', 'Juguete Deluxe Colita gatuna', 'Si le encanta atrapar pequeños objetos, esta colita está lista para entrar al juego. La Colita Gatuna combina una textura suave con un cuerpo ligero y catnip en su interior. Su tamaño mini permite que tu gato la tome entre sus patas y la explore a su manera.', '8 x 4,5 cm', (select id from public.categories where slug = 'gatos-juguetes-para-gato'), 'Talla', true, -1690) on conflict (slug) do nothing;
