insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('toallas-de-entrenamiento-x30', 'Toallas de entrenamiento x 30', 'Aprender dónde hacer sus necesidades es más sencillo cuando tiene un lugar preparado. Estos tapetes absorbentes ayudan a concentrar la humedad y cuentan con adhesivos en las cuatro esquinas para fijarlos al piso. Su formato de 60 x 60 cm acompaña el entrenamiento en casa con una superficie fácil de reconocer.', '60 x 60 cm por tapete', (select id from public.categories where slug = 'cuidado-cuidado-del-peludito'), 'Talla', true, -1680) on conflict (slug) do nothing;
