insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('peluche-importado-tiburon', 'Peluche importado Tiburón', 'Un tiburón con cara de travieso puede convertirse en su nuevo compañero de juegos. Su textura suave y sus aletas le dan detalles para tomar, llevar de un lado a otro o abrazar al descansar. La combinación de gris y morado le pone personalidad a este peluche que también puede acompañarlo en sus ratos tranquilos.', '17 x 31H cm', (select id from public.categories where slug = 'peluches-otros-peluches'), 'Talla', false, -1670) on conflict (slug) do nothing;
