insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-dumbbell-l', 'Juguete Dumbbell L', 'Un premio escondido puede convertir el juego en un pequeño reto. El Dumbbell L tiene forma de mancuerna y espacios para colocar snacks, de modo que tu perro pueda entretenerse intentando sacarlos. Su acabado translúcido y sus relieves añaden detalles para explorar mientras lo mueve y mordisquea.', 'L, 17,8 cm', (select id from public.categories where slug = 'juguetes-juguetes'), 'Talla', false, -1660) on conflict (slug) do nothing;
