insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-dumbbell-m', 'Juguete Dumbbell M', 'Si disfruta buscar sus premios, esta mancuerna le dará otra forma de encontrarlos. El Dumbbell M permite introducir snacks en sus aberturas para sumar una recompensa al momento de jugar. Tiene una superficie con relieves y un cuerpo translúcido que deja ver el contenido y despierta su curiosidad.', 'M, 15,2 cm', (select id from public.categories where slug = 'juguetes-juguetes'), 'Talla', false, -1650) on conflict (slug) do nothing;
