insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-deluxe-garrita-gatuna', 'Juguete Deluxe Garrita gatuna', 'Para los gatos que disfrutan sujetar su juguete y no soltarlo tan fácilmente. La Garrita Gatuna tiene una silueta alargada, textura suave y un peso ligero que facilita tomarla entre las patas. Incluye catnip para despertar su interés y sumar variedad a sus momentos de juego en casa.', '8,5 x 6,5 cm', (select id from public.categories where slug = 'gatos-juguetes-para-gato'), 'Talla', false, -1640) on conflict (slug) do nothing;
