insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('juguete-deluxe-garrita-felina-catnip', 'Juguete Deluxe Garrita felina', 'Un pequeño compañero de tela puede darle muchas razones para ponerse a jugar. La Garrita Felina contiene catnip y tiene una superficie suave que tu gato puede abrazar, atrapar o llevar de un lado a otro. Su diseño con detalles de gatito la hace tan simpática como fácil de incorporar a sus juegos.', '8,5 x 7,5 cm', (select id from public.categories where slug = 'gatos-juguetes-para-gato'), 'Talla', false, -1630) on conflict (slug) do nothing;
