insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('collar-para-gatos-pescaditos', 'Collar para gatos Pescaditos', 'Un estampado inspirado en algo que seguramente despertará su curiosidad: los pescaditos. Su tono azul combina con el diseño e incluye cascabel y argolla para añadir la placa de identificación.', null, (select id from public.categories where slug = 'gatos-collares-para-gato'), 'Talla', false, -1620) on conflict (slug) do nothing;
