insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('collar-para-gatos-espina-tommy', 'Collar para gatos Espina Tommy', 'Las espinas de pescado le dan un toque juguetón y muy gatuno a este collar. Puedes elegirlo en rojo o azul, y viene con cascabel y argolla para añadir su placa de identificación.', null, (select id from public.categories where slug = 'gatos-collares-para-gato'), 'Talla', false, -1600) on conflict (slug) do nothing;
