insert into public.products (slug, name, description, dimensions, category_id, variant_label, is_active, display_order) values ('correa-honey', 'Correa Honey', 'Diseñada para acompañar el arnés Honey y completar el conjunto. Su tejido de buen grosor se siente firme en la mano y te permite disfrutar el paseo con mayor confianza, sin dejar de lado el color y el estilo.', null, (select id from public.categories where slug = 'paseo-collares-y-correas-perros'), 'Talla', false, -1570) on conflict (slug) do nothing;
